import{_ as s,a0 as n,w as o,s as p,I as l,x as a,a1 as i,A as r,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 Gamerzilla 分享你的游戏成就 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Gamerzilla 分享你的游戏成就 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Gamerzilla 分享你的游戏成就 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Gamerzilla 分享你的游戏成就 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20230925 Share your game achievements with Gamerzilla","title":"使用 Gamerzilla 分享你的游戏成就","tag":"202310","desc":""},"relativePath":"202310/20230925 Share your game achievements with Gamerzilla.md","filePath":"[post].md"}'),d={name:"202310/20230925 Share your game achievements with Gamerzilla.md"};function u(g,e,f,h,b,z){const t=n("Link");return o(),p("div",null,[e[27]||(e[27]=l("h1",{id:"使用-gamerzilla-分享你的游戏成就",tabindex:"-1"},[a("使用 Gamerzilla 分享你的游戏成就 "),l("a",{class:"header-anchor",href:"#使用-gamerzilla-分享你的游戏成就","aria-label":"Permalink to “使用 Gamerzilla 分享你的游戏成就”"},"​")],-1)),e[28]||(e[28]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202310/08/191724uj7mmjw9ccd7pcl9.jpg",alt:""})],-1)),e[29]||(e[29]=l("p",null,"Gamerzilla 是一个开源游戏成就系统，用于存储和共享你的游戏成就。游戏使用 libgamerzilla 轻松添加成就。Gamerzilla 库是用 C 编写的，但也有其他语言的绑定。",-1)),l("p",null,[e[1]||(e[1]=a("两年前，我描述了如何设置 ",-1)),i(t,{href:"https://linux.cn/article-15389-1.html"},{default:r(()=>[...e[0]||(e[0]=[a("Gamerzilla 服务器",-1)])]),_:1}),e[2]||(e[2]=a("。除了 .net 实现之外，还可以使用 php 和 python 实现。但你可能不想运行自己的服务器。这里介绍一个公共服务器和 Gnome 界面。",-1))]),e[30]||(e[30]=l("h3",{id:"公共服务器",tabindex:"-1"},[a("公共服务器 "),l("a",{class:"header-anchor",href:"#公共服务器","aria-label":"Permalink to “公共服务器”"},"​")],-1)),l("p",null,[e[4]||(e[4]=a("我的网络服务器现在托管了一个启用了公共注册的 ",-1)),i(t,{href:"https://identicalsoftware.com/trophy/"},{default:r(()=>[...e[3]||(e[3]=[a("Gamerzilla",-1)])]),_:1}),e[5]||(e[5]=a(" 实例。要创建帐户，请单击右上角的 “",-1)),e[6]||(e[6]=l("ruby",null,[a("签到"),l("rt",null,"Sign In")],-1)),e[7]||(e[7]=a("” 链接。然后单击 “",-1)),e[8]||(e[8]=l("ruby",null,[a("登录"),l("rt",null,"Login")],-1)),e[9]||(e[9]=a("” 按钮旁边的 “",-1)),e[10]||(e[10]=l("ruby",null,[a("注册"),l("rt",null,"Register")],-1)),e[11]||(e[11]=a("” 链接。",-1))]),e[31]||(e[31]=m('<p>用户帐户收集的信息非常少。只需输入用户名和密码。你不需要输入你的真实姓名或电子邮件地址。因此，忘记密码没有实现。</p><p>账户一开始是不可见的。如果你希望公众在登录后看到你的成就，请单击页面右上角你的用户名，然后选择 “<ruby>设为可见<rt>Make Visible</rt></ruby>”。新用户必须经过批准才能上传成就。目前没有显示你是否获得批准的指示。</p><h3 id="获得成就" tabindex="-1">获得成就 <a class="header-anchor" href="#获得成就" aria-label="Permalink to “获得成就”">​</a></h3><p>在获得第一个成就之前，你需要使用以下命令安装 Gamerzilla GNOME Shell 扩展：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install gnome-shell-extension</span></span></code></pre></div><p>安装后，你需要注销并重新登录。需要使用以下命令启用扩展：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions enable gamerzilla@gamerzilla.identicalsoftware.com</span></span></code></pre></div><p>游戏控制器图标出现在 GNOME Shell 的顶部栏中。</p><p>单击控制器图标并选择 “<ruby>首选项<rt>preferences</rt></ruby>”。在出现的屏幕上输入你的 Gamerzilla 网址，包括尾部斜杠，但不包含 UI 的“奖杯”地址。如果使用我的服务器，该值将为 <code>https://identicalsoftware.com/</code>。填写你的用户名和密码。单击保存。默认情况下启用自动连接。如果你不想始终连接，请禁用此功能。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2023/09/gamerzilla_preferences.png" alt="Gamerzilla Controller menu"></p><p>不幸的是，一个错误阻止了该 Shell 扩展立即工作。你需要注销并重新登录。解决这个问题是当务之急。</p><h3 id="目前支持的游戏" tabindex="-1">目前支持的游戏 <a class="header-anchor" href="#目前支持的游戏" aria-label="Permalink to “目前支持的游戏”">​</a></h3><p>Fedora 仓库中的多个游戏支持 Gamerzilla 成就。如果你想买一个来尝试一下，我建议试试 Shippy 1984、Seahorse Adventures 或 Anagramarama。一旦你完成一个级别，Seahorse Adventures 就会存储一些进度。如果你玩 Super Tux Kart，你可能已经取得了成就。只需启动游戏即可同步之前完成的任何成就。当成就完成时，Gamerzilla 不会显示任何通知，但游戏可能会自行实现。</p><h3 id="更进一步" tabindex="-1">更进一步 <a class="header-anchor" href="#更进一步" aria-label="Permalink to “更进一步”">​</a></h3><p>除了修复第一次连接的错误之外，我还想要一个本地浏览器来查看成就。这样你就可以查看所有游戏成就，而无需强制上传它们。</p><p>成就确实有消极的一面。有些人觉得有必要完成它们。如果成就非常困难，这可能会导致负面的游戏体验。我理解这种担忧，但有些人也喜欢这些方面。更重要的是，为了吸引和留住玩家，我觉得开源游戏需要一个游戏成就系统。</p><p>我们需要更多游戏来实现 Gamerzilla 成就。我们需要玩家表现出对这个系统的支持。我继续为我的游戏和我尝试的其他开源游戏添加成就。</p><p><em>（题图：MJ/32ae3f54-b319-4db7-b874-eeacd1dcc4d2）</em></p><hr>',19)),l("p",null,[e[13]||(e[13]=a("via: ",-1)),i(t,{href:"https://fedoramagazine.org/share-your-game-achievements-with-gamerzilla/"},{default:r(()=>[...e[12]||(e[12]=[a("https://fedoramagazine.org/share-your-game-achievements-with-gamerzilla/",-1)])]),_:1})]),l("p",null,[e[18]||(e[18]=a("作者：",-1)),i(t,{href:"https://fedoramagazine.org/author/dulsi/"},{default:r(()=>[...e[14]||(e[14]=[a("Dennis Payne",-1)])]),_:1}),e[19]||(e[19]=a(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[15]||(e[15]=[a("lujun9972",-1)])]),_:1}),e[20]||(e[20]=a(" 译者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:r(()=>[...e[16]||(e[16]=[a("geekpi",-1)])]),_:1}),e[21]||(e[21]=a(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[17]||(e[17]=[a("wxy",-1)])]),_:1})]),l("p",null,[e[24]||(e[24]=a("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[22]||(e[22]=[a("LCTT",-1)])]),_:1}),e[25]||(e[25]=a(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:r(()=>[...e[23]||(e[23]=[a("Linux中国",-1)])]),_:1}),e[26]||(e[26]=a(" 荣誉推出",-1))])])}const G=s(d,[["render",u]]);export{y as __pageData,G as default};
